import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"How do I control covers, fans, locks and climate devices?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/03.referenz/04.cover-luefter-schloss-klima.md"},"headers":[],"relativePath":"adapter/esphome/referenz/cover-luefter-schloss-klima.md","filePath":"adapter/esphome/referenz/cover-luefter-schloss-klima.md","lastUpdated":1795562976000}'),s={name:"adapter/esphome/referenz/cover-luefter-schloss-klima.md"};function n(d,e,c,l,r,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="how-do-i-control-covers-fans-locks-and-climate-devices" tabindex="-1">How do I control covers, fans, locks and climate devices? <a class="header-anchor" href="#how-do-i-control-covers-fans-locks-and-climate-devices" aria-label="Permalink to &quot;How do I control covers, fans, locks and climate devices?&quot;">​</a></h1><p><a id="control-covers-including-time-based"></a></p><h2 id="how-do-i-control-covers-including-time-based-position-tilt-stop" tabindex="-1">How do I control covers (including time_based): position, tilt, stop? <a class="header-anchor" href="#how-do-i-control-covers-including-time-based-position-tilt-stop" aria-label="Permalink to &quot;How do I control covers (including time_based): position, tilt, stop?&quot;">​</a></h2><p>A cover has the states <code>position</code>, <code>tilt</code> and <code>stop</code> under <code>esphome.0.&lt;device&gt;.Cover.&lt;key&gt;</code>. You read and write position and tilt in percent: <code>0</code> = closed, <code>100</code> = open.</p><table tabindex="0"><thead><tr><th>State</th><th>Values</th><th>Role</th></tr></thead><tbody><tr><td><code>position</code></td><td>0 to 100 %</td><td><code>level.blind</code></td></tr><tr><td><code>tilt</code></td><td>0 to 100 %</td><td><code>level.tilt</code></td></tr><tr><td><code>stop</code></td><td>any written value stops the cover</td><td><code>button</code></td></tr></tbody></table><p>There is no separate state for open or close, you write <code>100</code> or <code>0</code> to <code>position</code>. If your cover has no tilt, ignore <code>tilt</code>. VIS sliders and voice assistants for the role <code>level.blind</code> work without conversion.</p><h3 id="how-to-move-a-blind-to-a-position" tabindex="-1">How to move a blind to a position <a class="header-anchor" href="#how-to-move-a-blind-to-a-position" aria-label="Permalink to &quot;How to move a blind to a position&quot;">​</a></h3><ol><li>In admin, open the &quot;Objects&quot; tab and go to <code>esphome.0.&lt;device&gt;.Cover.&lt;key&gt;</code>.</li><li>Write the target value to <code>position</code>, e.g. <code>30</code> for 30 % open.</li><li>The device starts moving and reports its position back. The state then shows it confirmed (<code>ack = true</code>).</li><li>To stop, write <code>true</code> to <code>stop</code>.</li></ol><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;device&gt;.Cover.&lt;key&gt;.position&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;device&gt;.Cover.&lt;key&gt;.stop&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>If <code>position</code> always stays at 0, the device reports no position through the API. For <code>time_based</code> covers this depends on the YAML, the adapter only shows what arrives.</p><p><strong>See also:</strong> <a href="./../anleitungen/automatisieren#use-esphome-datapoints-aliases-alexa">Using states in aliases</a> · <a href="./datenpunkte#command-acknowledged-ack-happens-offline">When a command counts as confirmed</a> · <a href="./datenpunkte#datapoint-path-contain-number-instead">Why the path contains a number</a></p><p><a id="control-esphome-fan-speed-direction"></a></p><h2 id="how-do-i-control-an-esphome-fan-speed-direction-oscillation" tabindex="-1">How do I control an ESPHome fan (speed, direction, oscillation)? <a class="header-anchor" href="#how-do-i-control-an-esphome-fan-speed-direction-oscillation" aria-label="Permalink to &quot;How do I control an ESPHome fan (speed, direction, oscillation)?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="operate-esphome-lock"></a></p><h2 id="how-do-i-operate-an-esphome-lock" tabindex="-1">How do I operate an ESPHome lock? <a class="header-anchor" href="#how-do-i-operate-an-esphome-lock" aria-label="Permalink to &quot;How do I operate an ESPHome lock?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="control-climate-device-example-midea"></a></p><h2 id="how-do-i-control-a-climate-device-for-example-a-midea-conversion" tabindex="-1">How do I control a climate device (for example a Midea conversion)? <a class="header-anchor" href="#how-do-i-control-a-climate-device-for-example-a-midea-conversion" aria-label="Permalink to &quot;How do I control a climate device (for example a Midea conversion)?&quot;">​</a></h2><p><em>This section is still being written.</em></p>`,20)])])}const k=o(s,[["render",n]]);export{m as __pageData,k as default};
